function loadPack(toolName, deps, fileOffset) {
  const pack = PACKS[toolName];
  if (!pack) return `Unknown pack: ${toolName}. Available: ${Object.keys(PACKS).join(", ")}`;
  const startIdx = fileOffset ?? 0;
  const parts = [];
  const paged = [];
  let usedLines = 0;
  for (let i = startIdx; i < pack.files.length; i++) {
    const filePath = pack.files[i];
    const doc = deps.resolveDocument(filePath);
    if (!doc) {
      parts.push(`## ${filePath}

*File not found \u2014 skipped.*`);
      continue;
    }
    const lines = doc.content.split("\n");
    const total = lines.length;
    if (usedLines > 0 && usedLines + total > PACK_TOTAL_BUDGET) {
      parts.push(`## ${filePath}

*Skipped \u2014 pack budget (${PACK_TOTAL_BUDGET} lines per call) reached. Use load_reference(path="${filePath}") to read this file.*`);
      paged.push(filePath);
      continue;
    }
    if (total <= PACK_FILE_CAP) {
      parts.push(`## ${filePath}

${doc.content}`);
      usedLines += total;
    } else {
      const chunk = lines.slice(0, PACK_FILE_CAP).join("\n");
      parts.push(`## ${filePath}

${chunk}

*PAGE REQUIRED: ${total - PACK_FILE_CAP} more lines \u2014 use load_reference(path="${filePath}", offset=${PACK_FILE_CAP}) to read the rest.*`);
      paged.push(filePath);
      usedLines += PACK_FILE_CAP;
    }
  }
  let text = parts.join("\n\n---\n\n");
  const fileCount = pack.files.length;
  if (startIdx > 0) {
    text += `

--- PromptMika pack notice: ${toolName} files ${startIdx + 1}-${pack.files.length} of ${fileCount} loaded. ---`;
  } else {
    text += `

--- PromptMika pack notice: ${toolName} \u2014 all ${fileCount} files loaded.${paged.length ? ` ${paged.length} file(s) were NOT served in full (${paged.join(", ")}) \u2014 load their remaining lines via load_reference before proceeding.` : ""} ---`;
  }
  return { text, paged, totalFiles: fileCount };
}
